    queue = [n]
    # Create a set to store unique numbers
    unique_numbers = set()
    # Loop until the queue is empty
    while queue:
        # Get the current number
        current_number = queue.pop(0)
        # If the current number is not in the set, add it and its transformed numbers to the queue
        if current_number not in unique_numbers:
            unique_numbers.add(current_number)
            for rule in rules:
                transformed_number = current_number
                for digit in str(current_number):
